class Spaceship {
  #fuel;
  #maxFuelCapacity = 100;

  constructor(initialFuel) {
    this.#fuel = Math.min(initialFuel, this.#maxFuelCapacity);
  }

  takeOff() {
    const fuelNeeded = 10;
    if (this.#fuel >= fuelNeeded) {
      this.#fuel -= fuelNeeded;
      return true;
    }
    return false;
  }

  refuel(amount) {
    this.#fuel = Math.min(this.#fuel + amount, this.#maxFuelCapacity);
  }

  getFuelLevel() {
    return this.#fuel;
  }
}

